#!/usr/bin/env python3
"""Export original M1 geometry and the approved maze-flow appearance for 星海解算主楼.

Requires Pillow. From the repository root:
    python -B src/test/python/export_star_sea_runtime.py --check
    python -B src/test/python/export_star_sea_runtime.py --output-root /path/to/output

--check compares generated bytes without writing any files. Without --check, the
nine generated files are written beneath --output-root (the repository by default).
The source models/textures in src/test/resources/fixtures/star_sea_calculation/
are always read-only; no concept previews or helper scripts are required.
A cabinet UV correction projects every casing slice in Minecraft's face orientation,
joining its outer border and circuits across the front/side seams. The real ME
port frames retain only their inner circuit artwork.

Runtime JSON coordinates are bb / 8 + (8, 0, 8), and UVs are bb / 32.
The BER/ghost helper restores scale 8 around the front-center bottom core. The
item uses the MINI geometry directly, with legal display scales. The shell
includes selected, slightly offset full-bright faces with a transparent animated
emissive mask; ordinary casing remains world-lit. Both sheets contain 32 frames
at two ticks per frame, retaining the logical 512 x 512 UV coordinates.

The two base slabs are partitioned around the new front-center white ME port.
The resulting 120 cuboids supply both the visuals and collision, at
bb / 16 + (.5, 0, 2.5), clipped to the same 225 reserved cells.
"""

from __future__ import annotations

import argparse
import copy
import io
import json
import math
from decimal import Decimal
from pathlib import Path
import uuid

from PIL import Image, ImageChops, ImageDraw

REPO_ROOT = Path(__file__).resolve().parents[3]
FIXTURE_DIR = REPO_ROOT / "src/test/resources/fixtures/star_sea_calculation"
SOURCE_DIR = FIXTURE_DIR / "m1-compact-tower"
SOURCE_MODEL = SOURCE_DIR / "star-listener-m1.bbmodel"
FLOW_DIR = FIXTURE_DIR / "m1-controller-maze-flow" / "animation"
FRAME_SIZE = 512
FRAME_COUNT = 32
GLOW_OFFSET = .002
ASSETS = Path("src/main/resources/assets/molecularmanipulator")
MODEL_DIR = ASSETS / "models/block/star_sea_calculation_mainframe"
TEXTURE_DIR = ASSETS / "textures/block/star_sea_calculation_mainframe"
GEOMETRY_JAVA = Path(
    "src/main/java/com/atir/molecularmanipulator/block/StarSeaCalculationGeometry.java"
)
RESOURCE = "molecularmanipulator:block/star_sea_calculation_mainframe"
GLASS_UUIDS = frozenset({"dc28d5fa-530d-5d5b-b835-db1c13427be4"})
SIDES = frozenset({"north", "south", "east", "west", "up", "down"})
PORT_NAME = "底座正中 / 白色 ME 接线端口"
# Blockbench units: the front-center bottom cell, flush with the 5 x 5 footprint.
PORT_FROM = [-8, 0, -40]
PORT_TO = [8, 16, -36]


def connection_port() -> Image.Image:
    """Original concentric teal socket on a white casing, inspired by the reference."""
    image = Image.new("RGBA", (16, 16), "#c7ced0")
    draw = ImageDraw.Draw(image)
    for box, color in [((2, 2, 13, 13), "#1c272b"), ((3, 3, 12, 12), "#252e30"),
                       ((4, 4, 11, 11), "#607275"), ((5, 5, 10, 10), "#398d79"),
                       ((6, 6, 9, 9), "#164e46"), ((7, 7, 8, 8), "#8ad9c8")]:
        draw.rectangle(box, fill=color)
    draw.line((5, 5, 7, 5), fill="#8ad9c8")
    draw.point((9, 5), fill="#8ad9c8")
    draw.line((5, 6, 5, 7), fill="#61b69f")
    return image


def clipped_element(element: dict, low: list, high: list, label: str) -> dict:
    """Split the original base around the port while preserving continuous face UVs."""
    result = copy.deepcopy(element)
    result.update(name=element["name"] + " / " + label, **{"from": low, "to": high},
                  uuid=str(uuid.uuid5(uuid.UUID(element["uuid"]), label)))
    # Each face uses its original orientation and the same affine UV projection.
    axes = {"north": (0, 1, False, True), "south": (0, 1, True, True),
            "east": (2, 1, False, True), "west": (2, 1, True, True),
            "up": (0, 2, False, True), "down": (0, 2, False, False)}
    for side, face in result["faces"].items():
        u_axis, v_axis, flip_u, flip_v = axes[side]
        ends = []
        for axis, flipped in ((u_axis, flip_u), (v_axis, flip_v)):
            start, end = element["from"][axis], element["to"][axis]
            a, b = (low[axis] - start) / (end - start), (high[axis] - start) / (end - start)
            ends.append((1 - b, 1 - a) if flipped else (a, b))
        u0, v0, u1, v1 = element["faces"][side]["uv"]
        face["uv"] = [u0 + ends[0][0] * (u1 - u0), v0 + ends[1][0] * (v1 - v0),
                      u0 + ends[0][1] * (u1 - u0), v0 + ends[1][1] * (v1 - v0)]
    return result


def runtime_source(source: dict) -> dict:
    """Add a square bottom-front socket without overlapping the original base skins."""
    result = copy.deepcopy(source)
    elements, replacements = [], {}
    for original in source["elements"]:
        if original["name"] not in {"承重底座", "完整面板"}:
            elements.append(copy.deepcopy(original))
            continue
        lo, hi = original["from"], original["to"]
        bounds = [
            (lo, [-8, hi[1], hi[2]], "端口左侧"),
            ([8, lo[1], lo[2]], hi, "端口右侧"),
            ([-8, lo[1], -36], [8, hi[1], hi[2]], "端口后侧"),
        ]
        pieces = [clipped_element(original, list(a), list(b), label) for a, b, label in bounds]
        replacements[original["uuid"]] = [element["uuid"] for element in pieces]
        elements.extend(pieces)
    port = {"name": PORT_NAME, "uuid": str(uuid.uuid5(uuid.NAMESPACE_URL, "omnisequence:star-sea-base-port")),
            "type": "cube", "from": PORT_FROM, "to": PORT_TO, "origin": [0, 0, 0],
            "rotation": [0, 0, 0], "inflate": 0, "box_uv": False, "autouv": 0,
            "faces": {side: {"uv": list(FLAT_SHELL_UV), "texture": 0}
                      for side in ("north", "south", "east", "west", "up", "down")}}
    port["faces"]["north"] = {"uv": [0, 0, 16, 16], "texture": 1}
    elements.append(port)
    result["elements"] = elements

    def replace(entries):
        updated = []
        for entry in entries:
            if isinstance(entry, str):
                updated.extend(replacements.get(entry, [entry]))
            else:
                entry["children"] = replace(entry["children"])
                updated.append(entry)
        return updated

    result["outliner"] = replace(result["outliner"])
    result["outliner"][0]["children"].append(port["uuid"])
    return result


def material(element: dict) -> str:
    """The source atlas is shared, so texture index cannot identify glass."""
    name = element.get("name", "").casefold()
    return "glass" if (
        element.get("uuid") in GLASS_UUIDS or "glass" in name or "玻璃" in name
    ) else "shell"


def converted(value: float, divisor: int, offset: float = 0) -> float:
    # Decimal avoids accumulating binary artifacts into generated Java/JSON.
    return float(Decimal(str(value)) / divisor + Decimal(str(offset)))


def validate_source(source: dict) -> None:
    elements = source["elements"]
    if len(elements) != 115 or len({e["uuid"] for e in elements}) != 115:
        raise ValueError("Expected the original 115 uniquely identified M1 cubes")
    if source["resolution"] != {"width": 512, "height": 512}:
        raise ValueError("UV conversion requires the original 512 x 512 atlas")

    def unrotated(node: dict) -> None:
        if any(node.get("rotation", (0, 0, 0))):
            raise ValueError(f"Rotated source node is not supported: {node.get('name')}")
        for child in node.get("children", ()):
            if isinstance(child, dict):
                unrotated(child)

    for group in source.get("outliner", []) + source.get("groups", []):
        if isinstance(group, dict):
            unrotated(group)
    for element in elements:
        unrotated(element)
        if element.get("type") != "cube" or element.get("inflate", 0):
            raise ValueError("Only the original, non-inflated cuboids are supported")
        if set(element["faces"]) != SIDES:
            raise ValueError("Every original cube must retain all six faces")
        for axis, offset in enumerate((8, 0, 8)):
            lo, hi = element["from"][axis], element["to"][axis]
            if not (math.isfinite(lo) and math.isfinite(hi) and lo < hi):
                raise ValueError("Invalid source cuboid bounds")
            if not (-16 <= converted(lo, 8, offset) < converted(hi, 8, offset) <= 32):
                raise ValueError("Miniature element is outside vanilla JSON bounds")
        for face in element["faces"].values():
            if face.get("texture") != 0 or len(face["uv"]) != 4:
                raise ValueError("Expected the original atlas-backed face UVs")
            if any(not math.isfinite(v) or not 0 <= v <= 512 for v in face["uv"]):
                raise ValueError("UV outside the original atlas")
            if face.get("rotation", 0) not in (0, 90, 180, 270):
                raise ValueError("Invalid face UV rotation")
    if sum(material(e) == "glass" for e in elements) != 1:
        raise ValueError("Expected exactly one original inspection glass cube")


CABINET_FRONT_PARTS = frozenset({"下部踢板", "上部解码面板", "接口中隔梁", "接口侧立框"})
CABINET_SHELL_PARTS = CABINET_FRONT_PARTS | {"解码机柜 / 后壳"}
FLAT_SHELL_UV = [344.5, 464.5, 359.5, 479.5]  # material_14: plain structural white
DECORATED_SHELL_UV = [8.5, 464.5, 23.5, 479.5]  # material_0: gray registration marks


def cabinet_face_uv(element: dict, side: str) -> list[float]:
    """Project one physical cabinet face using FaceInfo/BlockFaceUV's native axes.

    Minecraft U increases toward -X on NORTH, +X on SOUTH, -Z on EAST
    and +Z on WEST. Cropping each slice in the opposite direction puts the
    island's outer white edge at an internal joint, even if the UV ranges touch.
    """
    lo, hi = element["from"], element["to"]
    axis = 0 if side in {"north", "south"} else 2
    u0, u1 = (lo[axis] + 22.4) / 44.8, (hi[axis] + 22.4) / 44.8
    if side in {"north", "east"}:
        u0, u1 = 1 - u1, 1 - u0
    v0, v1 = (35.2 - hi[1]) / 25.6, (35.2 - lo[1]) / 25.6
    x, y = {"north": (208, 272), "south": (272, 272),
            "east": (208, 320), "west": (272, 320)}[side]
    return [x + .5 + u0 * 47, y + .5 + v0 * 31,
            x + .5 + u1 * 47, y + .5 + v1 * 31]


def corrected_face_uv(element: dict, side: str) -> list[float]:
    """Keep archived bounds/artwork; repair native cabinet projection and port rims."""
    original = element["faces"][side]["uv"]
    name = element["name"]
    if name == "内嵌 ME 接口面板" and side == "north":
        # The real .09-block bezel already supplies the frame. Sample only the
        # inner 12 x 12 circuit field, excluding the redundant two-pixel white rim.
        u0, v0, u1, v1 = original
        return [u0 + 2, v0 + 2, u1 - 2, v1 - 2]
    if name not in CABINET_SHELL_PARTS:
        return original
    lo, hi = element["from"], element["to"]
    exterior = ((side == "north" and lo[2] == -22.4)
                or (side == "south" and hi[2] == 22.4)
                or (side == "east" and hi[0] == 22.4)
                or (side == "west" and lo[0] == -22.4))
    if exterior:
        # Rear AND front slices must use the same projection at the same world
        # position. Fixing just the narrow front strip leaves the seam reversed.
        return cabinet_face_uv(element, side)
    # Hidden joints and exposed pocket returns use a flat swatch rather than
    # stretching the small decorated machine-face texture over each thin strip.
    return FLAT_SHELL_UV if name in CABINET_FRONT_PARTS and original == DECORATED_SHELL_UV else original


def runtime_element(element: dict) -> dict:
    faces = {}
    for side, source_face in element["faces"].items():
        port = source_face.get("texture") == 1
        face = {"uv": [converted(v, 1 if port else 32) for v in corrected_face_uv(element, side)],
                "texture": "#port" if port else "#atlas"}
        if source_face.get("rotation", 0):
            face["rotation"] = source_face["rotation"]
        # No cullface: the shared helper submits only the null-side list ONCE.
        faces[side] = face
    return {
        "name": element["name"],
        "from": [converted(v, 8, o) for v, o in zip(element["from"], (8, 0, 8))],
        "to": [converted(v, 8, o) for v, o in zip(element["to"], (8, 0, 8))],
        "faces": faces,
    }


def json_bytes(value: dict) -> bytes:
    return (json.dumps(value, ensure_ascii=False, indent=2) + "\n").encode("utf-8")


def model_bytes(elements: list[dict], layer: str) -> bytes:
    # One source cube per line keeps these generated files reasonably compact.
    model = {
        "ambientocclusion": False,
        "render_type": "minecraft:" + layer,
        "textures": {"atlas": RESOURCE + "/array_atlas", "particle": "#atlas"},
        "elements": [],
    }
    if layer == "cutout":
        model["textures"].update(emissive=RESOURCE + "/array_emissive", port=RESOURCE + "/me_connection_port")
    text = json.dumps(model, ensure_ascii=False, indent=2)
    rows = ",\n".join("    " + json.dumps(e, ensure_ascii=False, separators=(",", ":")) for e in elements)
    return (text.replace('"elements": []', '"elements": [\n' + rows + "\n  ]") + "\n").encode("utf-8")


def display(rotation: tuple, translation: tuple, scale: float) -> dict:
    return {"rotation": rotation, "translation": translation, "scale": [scale] * 3}


def item_model() -> dict:
    return {
        "parent": "minecraft:block/block",
        "loader": "neoforge:composite",
        "gui_light": "side",
        "textures": {"particle": RESOURCE + "/array_atlas"},
        "children": {
            "shell": {"parent": RESOURCE + "/shell"},
            "glass": {"parent": RESOURCE + "/glass"},
        },
        "item_render_order": ["shell", "glass"],
        "display": {
            "gui": display((25, 225, 0), (0, -.8, 0), .8),
            "ground": display((0, 0, 0), (0, 3, 0), .5),
            "fixed": display((0, 0, 0), (0, -.75, 0), .75),
            "head": display((0, 0, 0), (0, 0, 0), 1),
            "thirdperson_righthand": display((75, 45, 0), (0, 2.5, 0), .6),
            "thirdperson_lefthand": display((75, 45, 0), (0, 2.5, 0), .6),
            "firstperson_righthand": display((0, 45, 0), (0, 0, 0), .6),
            "firstperson_lefthand": display((0, 225, 0), (0, 0, 0), .6),
        },
    }


GEOMETRY_TEMPLATE = '''package com.atir.molecularmanipulator.block;

import net.minecraft.core.BlockPos;
import net.minecraft.core.Direction;
import net.minecraft.world.phys.shapes.BooleanOp;
import net.minecraft.world.phys.shapes.Shapes;
import net.minecraft.world.phys.shapes.VoxelShape;

/**
 * Generated from M1 fixtures in src/test/resources/fixtures/star_sea_calculation/
 * plus the bottom-center port by src/test/python/export_star_sea_runtime.py.
 * The core is the front-center BOTTOM cell, not the tower's center or mid-height.
 * PART is canonical NORTH: y * 25 + z * 5 + (x + 2), x=-2..2, y=0..8, z=0..4.
 * Placement reserves all 225 cells, but collision/click shapes contain only real
 * cuboids. A PART keeps its canonical index for every facing; move its block via
 * offset(part, facing), and use shape(part, facing) inside that rotated block.
 */
public final class StarSeaCalculationGeometry {
    public static final int PART_COUNT = 225;
    // bb / 16 + (.5, 0, 2.5), relative to the core's lower corner; 120 rows.
    private static final double[][] CUBOIDS = {
__CUBOIDS__
    };
    private static final VoxelShape[][] SHAPES = buildShapes();

    private StarSeaCalculationGeometry() {}

    /** Exact cell-local geometry, including an empty shape for unoccupied cells. */
    public static VoxelShape shape(int part, Direction facing) {
        return SHAPES[quarterTurns(facing)][java.util.Objects.checkIndex(part, PART_COUNT)];
    }

    public static int partIndex(int x, int y, int z) {
        if (x < -2 || x > 2 || y < 0 || y > 8 || z < 0 || z > 4) {
            throw new IllegalArgumentException("Outside the canonical 5 x 9 x 5 reservation");
        }
        return y * 25 + z * 5 + x + 2;
    }

    public static int offsetX(int part) { return java.util.Objects.checkIndex(part, PART_COUNT) % 5 - 2; }
    public static int offsetY(int part) { return java.util.Objects.checkIndex(part, PART_COUNT) / 25; }
    public static int offsetZ(int part) { return java.util.Objects.checkIndex(part, PART_COUNT) / 5 % 5; }

    public static BlockPos offset(int part) {
        return new BlockPos(offsetX(part), offsetY(part), offsetZ(part));
    }

    public static BlockPos offset(int part, Direction facing) {
        return rotateOffset(offset(part), facing);
    }

    public static int quarterTurns(Direction facing) {
        return switch (facing) {
            case NORTH -> 0;
            case EAST -> 1;
            case SOUTH -> 2;
            case WEST -> 3;
            default -> throw new IllegalArgumentException("Horizontal facing required");
        };
    }

    /** Same -90*q Y rotation as the render helper, around the core's center. */
    public static BlockPos rotateOffset(BlockPos offset, Direction facing) {
        int x = offset.getX(), y = offset.getY(), z = offset.getZ();
        return switch (quarterTurns(facing)) {
            case 0 -> offset;
            case 1 -> new BlockPos(-z, y, x);
            case 2 -> new BlockPos(-x, y, -z);
            default -> new BlockPos(z, y, -x);
        };
    }

    private static VoxelShape[][] buildShapes() {
        var result = new VoxelShape[4][PART_COUNT];
        for (int part = 0; part < PART_COUNT; part++) {
            int x = offsetX(part), y = offsetY(part), z = offsetZ(part);
            var north = Shapes.empty();
            for (double[] box : CUBOIDS) {
                double x0 = Math.max(box[0], x), y0 = Math.max(box[1], y), z0 = Math.max(box[2], z);
                double x1 = Math.min(box[3], x + 1), y1 = Math.min(box[4], y + 1), z1 = Math.min(box[5], z + 1);
                if (x0 >= x1 || y0 >= y1 || z0 >= z1) continue;
                north = Shapes.joinUnoptimized(north,
                        Shapes.box(x0 - x, y0 - y, z0 - z, x1 - x, y1 - y, z1 - z), BooleanOp.OR);
            }
            result[0][part] = north.optimize();
            // Rotate the already clipped local voxels, NEVER the PART number.
            var boxes = result[0][part].toAabbs();
            for (int turns = 1; turns < 4; turns++) {
                var rotated = Shapes.empty();
                for (var box : boxes) {
                    var piece = switch (turns) {
                        case 1 -> Shapes.box(1 - box.maxZ, box.minY, box.minX,
                                1 - box.minZ, box.maxY, box.maxX);
                        case 2 -> Shapes.box(1 - box.maxX, box.minY, 1 - box.maxZ,
                                1 - box.minX, box.maxY, 1 - box.minZ);
                        default -> Shapes.box(box.minZ, box.minY, 1 - box.maxX,
                                box.maxZ, box.maxY, 1 - box.minX);
                    };
                    rotated = Shapes.joinUnoptimized(rotated, piece, BooleanOp.OR);
                }
                result[turns][part] = rotated.optimize();
            }
        }
        return result;
    }
}
'''


def geometry_java(elements: list[dict]) -> bytes:
    rows = []
    for element in elements:
        bounds = [converted(v, 16, o) for key in ("from", "to")
                  for v, o in zip(element[key], (.5, 0, 2.5))]
        rows.append("        {" + ", ".join(str(v) for v in bounds) + "},")
    return GEOMETRY_TEMPLATE.replace("__CUBOIDS__", "\n".join(rows)).encode("utf-8")


def animated_emission() -> tuple[bytes, Image.Image]:
    """Black means no glow, never an opaque black overlay covering the casing."""
    image = Image.open(FLOW_DIR / "array_emissive.png").convert("RGBA")
    if image.size != (FRAME_SIZE, FRAME_SIZE * FRAME_COUNT):
        raise ValueError("Expected a 32-frame 512 x 512 emissive animation")
    alpha = image.convert("L").point(lambda value: 255 if value else 0)
    image.putalpha(alpha)
    union = Image.new("L", (FRAME_SIZE, FRAME_SIZE))
    for frame in range(FRAME_COUNT):
        union = ImageChops.lighter(union, alpha.crop((0, frame * FRAME_SIZE,
                                                   FRAME_SIZE, (frame + 1) * FRAME_SIZE)))
    raw = io.BytesIO()
    image.save(raw, format="PNG", optimize=True)
    return raw.getvalue(), union


def glow_elements(elements: list[dict], mask: Image.Image) -> list[dict]:
    """Offset each luminous face only along its normal, preserving edge alignment."""
    result = []
    for element in elements:
        if material(element) == "glass":
            continue
        mini = runtime_element(element)
        for side, face in mini["faces"].items():
            if face["texture"] != "#atlas":
                continue  # The connection socket is a static, world-lit texture.
            u0, v0, u1, v1 = corrected_face_uv(element, side)
            bounds = (math.floor(min(u0, u1)), math.floor(min(v0, v1)),
                      math.ceil(max(u0, u1)), math.ceil(max(v0, v1)))
            if not mask.crop(bounds).getbbox():
                continue
            axis, direction = {"west": (0, -1), "east": (0, 1),
                               "down": (1, -1), "up": (1, 1),
                               "north": (2, -1), "south": (2, 1)}[side]
            low, high = mini["from"].copy(), mini["to"].copy()
            # Expanding all axes stretched UVs and made neighboring faces overlap
            # at the shell seams. Translation leaves both in-plane axes exact.
            low[axis] = round(low[axis] + direction * GLOW_OFFSET, 8)
            high[axis] = round(high[axis] + direction * GLOW_OFFSET, 8)
            result.append({
                "name": element["name"] + " / 流光 / " + side,
                "from": low,
                "to": high,
                "shade": False,
                "neoforge_data": {"block_light": 15, "sky_light": 15, "ambient_occlusion": False},
                "faces": {side: {**face, "texture": "#emissive"}},
            })
    return result


def generated_files() -> dict[Path, bytes]:
    source = json.loads(SOURCE_MODEL.read_text(encoding="utf-8"))
    validate_source(source)
    elements = runtime_source(source)["elements"]
    port_png = io.BytesIO()
    connection_port().save(port_png, format="PNG", optimize=True)
    emission, mask = animated_emission()
    shell = [runtime_element(e) for e in elements if material(e) == "shell"]
    shell.extend(glow_elements(elements, mask))
    return {
        MODEL_DIR / "shell.json": model_bytes(shell, "cutout"),
        MODEL_DIR / "glass.json": model_bytes(
            [runtime_element(e) for e in elements if material(e) == "glass"], "translucent"),
        ASSETS / "models/item/star_sea_calculation_mainframe.json": json_bytes(item_model()),
        TEXTURE_DIR / "array_atlas.png": (FLOW_DIR / "array_atlas.png").read_bytes(),
        TEXTURE_DIR / "array_emissive.png": emission,
        TEXTURE_DIR / "array_atlas.png.mcmeta": (FLOW_DIR / "array_atlas.png.mcmeta").read_bytes(),
        TEXTURE_DIR / "array_emissive.png.mcmeta": (FLOW_DIR / "array_emissive.png.mcmeta").read_bytes(),
        TEXTURE_DIR / "me_connection_port.png": port_png.getvalue(),
        GEOMETRY_JAVA: geometry_java(elements),
    }


def main() -> int:
    parser = argparse.ArgumentParser(description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter)
    parser.add_argument("--output-root", type=Path, default=REPO_ROOT)
    parser.add_argument("--check", action="store_true", help="Verify generated bytes without writing anything")
    args = parser.parse_args()
    mismatches = []
    for relative, data in generated_files().items():
        target = args.output_root / relative
        if args.check:
            if not target.is_file() or target.read_bytes() != data:
                mismatches.append(relative)
        else:
            target.parent.mkdir(parents=True, exist_ok=True)
            target.write_bytes(data)
            print(relative.as_posix())
    for relative in mismatches:
        print("Missing or stale: " + relative.as_posix())
    if not mismatches:
        print("M1 runtime: 120 cubes, white bottom-center port, 32 flow frames, nine generated files verified" if args.check
              else "Exported M1 with white bottom-center ME port; retained test fixtures unchanged")
    return 1 if mismatches else 0


if __name__ == "__main__":
    raise SystemExit(main())
